DEFERRED={
'coadjutor':'教会等特定组织的辅助职务名，先掌握 aide/adjutant。','jocund':'较少用的文学形容词，先保留常用帮助支线。','adjument':'古旧帮助名词，暂略。','adjutor':'古旧助手名词，暂略。','adjutory':'古旧辅助形容词或特定旧医学名词，暂略。','adjutrix':'罕见旧式女性助手名称，暂略。','coadjutant':'少用的助手近义名词或形容词，暂略。','injucundity':'罕见的令人不快性质名词，暂略。','jocundity':'较少用的欢快性质名词，暂略。',
'hypnopompic':'睡眠过渡的专门术语，暂略。','apopemptic':'古典送别作品的罕见形容词，暂略。','hyenoid':'少用的鬣狗状形容词，暂略。','phyllotaxis':'叶序的专门植物学术语，暂略。',
'paraclete':'特定基督教称谓，暂略。','epiclesis':'特定礼仪祈祷名称，暂略。','ecclesiophobia':'少用的教会恐惧名称，暂略。','Ecclesiastes':'圣经书卷专名，暂不另列通用学习条目。'}
ALREADY={'psychopomp','recede','chlorophyll','ecclesiology','reuse','reapply','return','semen','seminal','seminar','seminary','seminarian','disseminate','dissemination','insemination','ecclesiastical'}
CATALOG={r['id']:r for r in json.loads(Path('.cache/catalog.json').read_text())}
def rootwords(i,extra=()):return list(dict.fromkeys([w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED and '-' not in w]+list(extra)))
def rootexclude(i):
 r=ASSIGN['roots'][i];c=CATALOG[r['id']];return {w:DEFERRED[w] for w in set(r['family'])|set(c['family'])|set(c['words'])|set(c['unmatched']) if w in DEFERRED}
JUV_ROOT=dict(id='C0628',meaning='帮助；给予支持',core='一个人力量不够，另一个人伸手补上，让事情继续向前。',image='拉丁 ad + iuvare → adiuvare；名词 adiuta、动词 adiutare 两支 → 古法语 aide／aidier → aid；助手职衔 → aide；adiutant- → adjutant。',intro='最实用的是 aid 帮助、援助，aide 助手和 unaided 独力的。adjutant 是军事岗位副官。几个词都与帮助相连，却有不同借入路线，不能看现代拼写长短就决定谁生出谁。',forms='juv-、jut- 反映拉丁帮助词族的不同词形。i 与 j 在拉丁转写中会交替出现。aid、aide 都读 /eɪd/；unaided 的末尾 -ed 读 /ɪd/。',branches=[['援助、帮助与辅助物','aid'],['提供帮助的人','aide, adjutant'],['没有外部援助','unaided']],contrasts='aid 通常是帮助或工具，aide 是人；adjutant 则有军事岗位背景。它们的共同源头不等于现代每个语境可以互换。',practice='用 aid 写一句提供物资的句子，再把提供帮助的人写成 aide，最后用 unaided 描述完全靠自己完成的事。',words=rootwords(288),exclude=rootexclude(288))
PEMP_ROOT=dict(id='C0987',meaning='派送；护送；仪式行列',core='从送出一支队伍，到隆重的队列与排场，再到人刻意摆出的架子。',image='希腊 pempein → pompe → 拉丁 pompa → pomp；pomposus → pompous，pompositas → pomposity；pompous + -ly → pompously。psyche + pompos 另成 psychopomp。',intro='pomp 可以是中性的隆重场面；pompous、pomposity、pompously 多批评自命不凡的姿态。psychopomp 保留送行、引导的核心，在神话里指亡灵的引路者。',forms='pomp 重音不难，只有一个音节；pompous 重音在前，pomposity 移到第二音节。pomposity 有拉丁名词借入史，不只看作英语形容词改后缀。',branches=[['仪式的盛大排场','pomp'],['把自己摆得过分重要','pompous, pomposity, pompously'],['神话中的引路与护送','psychopomp']],contrasts='formal 只是正式，pompous 往往让人反感；仪式有 pomp 不等于每个参与者都 pompous。',practice='分别描写一场隆重但得体的仪式、一个故作庄严的讲话者，用 pomp 和 pompous 体现褒贬差异。',words=rootwords(289),exclude=rootexclude(289))
ORG_ROOT=dict(id='C0916',meaning='兴奋；膨胀；激动',core='这组古词描述兴奋、膨胀等状态，英语中最常见的是性高潮名称。',image='希腊 organ／orgao → orgasmos → 法语 orgasme 或近代拉丁 orgasmus → 英语 orgasm → orgasmic。',intro='orgasm 是性高潮，也可作动词；orgasmic 是与高潮有关的形容词，口语偶有强烈夸张。这里的源头是希腊兴奋、膨胀词族，不能用 work 工作解释。',forms='orgasm 重音在前，orgasmic 重音移到 -gasm-。古希腊转写 organ 是动词形式，不等于现代英语 organ 器官；同样不能与 ergon 工作硬合为一根。',branches=[['体验与达到高峰的动作','orgasm'],['相应形容词及夸张比喻','orgasmic']],contrasts='arousal 兴奋是较宽的状态，orgasm 是高潮；词源中的膨胀也不能直接作为现代定义。',practice='用 orgasm 与 orgasmic 各写一句中性说明，观察名词与形容词的句法位置和重音差异。',words=rootwords(290),exclude=rootexclude(290))
HYS_ROOT=dict(id='C0587',meaning='猪；由硬鬃毛引出的动物命名',core='古人看到动物身上的硬毛，会借另一种熟悉动物的名称来称呼它。',image='希腊 hys 猪 → hyaina 鬣狗〔传统命名解释〕→ 拉丁 hyaena → 古法语 hiene → 英语 hyena。',intro='这一组先掌握 hyena。它与猪的联系是传统词源分析中的外貌比喻，不是生物分类，也不是说英语里 pig 可以直接代替 hyena。',forms='hyena 读 /haɪˈiːnə/，重音在中间；hyaena 是另一拼法。现代常见搭配有 spotted hyena、striped hyena。',branches=[['野生动物名称与外貌比喻','hyena']],contrasts='laugh like a hyena 是人的语言比喻，不能据此把动物叫声解释成人类笑声的情绪含义。',practice='用 hyena 写一句野生动物观察记录，再说明名字里像猪的联想为什么不是分类结论。',words=rootwords(291),exclude=rootexclude(291))
RE_ROOT=dict(id='C1208',meaning='再一次；回到原处或原状态',core='把一个动作再做一遍，或把偏离、损坏的东西带回原先的状态。',image='拉丁 re-／red- → 古法语及英语 re-；英语自由组合 redo、rewrite、rethink、rebuild；借词路线 redigere → redact、restaurare → restore。',intro='先把两种常见画面分开：redo、rewrite 是再做，restore、return 是恢复或回去。re- 可以接英语本族词，所以 rewrite 并不是整词来自拉丁。另一方面，老借词中的意思常已变化，不能把每个 re 开头的词都机械译成再一次。',forms='古拉丁 red- 常见于元音前的形式，保存在 redact 等词里。现代透明组合中的 re- 常读 /riː/，如 redo；旧借词常有弱读 /rɪ/，如 restore。rewrite、rethink 的名词与动词重音还不同。',branches=[['再做、再写、再使用','redo, rewrite, reuse, reusable, reapply'],['重新考虑与重新排列','rethink, reconsider, reconsideration, rearrange, rearrangement'],['重建、续期与更新','rebuild, renew, renewal'],['回到原处、原状态','restore, restoration, return, recede'],['归整文本与删隐内容','redact, redaction, redacted']],contrasts='rethink 不保证最后改主意，renew 不等于换一件新东西，restore 也不是再存进仓库。redact 的现代删隐义要从整个词的历史和用法理解。',practice='把一篇稿件重写、一次订阅续期、一份备份还原，分别选 rewrite、renew、restore；再解释为何不是所有三种任务都用同一个重做。',words=rootwords(292,['reuse','reapply','return']),exclude=rootexclude(292))
SEMIN_ROOT=dict(id='C1305',meaning='种子；播种；培养与传播',core='种子被撒下、培养、长出后续事物，便能比喻知识、人才和思想的传播。',image='拉丁 semen，词干 semin- → seminalis／seminarium／seminare；培养之地 → seminary、经德语 Seminar → seminar；disseminare → disseminate；inseminare → inseminate。',intro='semen 留下生殖义，seminal 也说开创性的思想；seminary 把学校比作育苗地，seminar 经德语用于研讨学习。disseminate 像把信息撒向各处，inseminate 则接向内播种的命名。',forms='semen 的词干是 semin-，不是英语单词删掉一个字母再随意拼接。seminar 与 seminary 有不同借入路线；dissemination、insemination 则是对应的过程名词。',branches=[['生物意义上的种子与生殖过程','semen, seminal, inseminate, insemination'],['培养人才与研讨学习','seminary, seminarian, seminar'],['向四处传播','disseminate, dissemination']],contrasts='seminar 通常是研讨活动或课程，seminary 现代常指神学院；inseminate 的授精过程不等于一定完成卵的受精或形成妊娠。',practice='用 seminarium 苗圃这个古老画面解释 seminar 与 seminary，再比较 disseminate information 和 inseminate 的不同方向。',words=rootwords(293,['semen','seminal','seminar','seminary','seminarian','disseminate','dissemination']),exclude=rootexclude(293))
PHYLL_ROOT=dict(id='C1033',meaning='叶；像叶子一样的薄片',core='一片薄而平的叶子，既进入植物色素的名称，也成为薄面皮的比喻。',image='希腊 phyllon 叶 + chloros 绿色 → chlorophyll；phyllon → 现代希腊薄面皮名称 → phyllo／filo。',intro='chlorophyll 是叶绿素，命名里的 leaf 提醒它与植物绿色相关；phyllo 则在厨房里指薄如叶片的面皮。两种用途不互相派生，而是各自利用叶的材料或形状。',forms='phyll-、phyllo- 来自叶；philo- 爱好与它不是同一个词根。面皮 phyllo 与 filo 是两种拼法，ph 在前者读 /f/。',branches=[['植物色素命名','chlorophyll'],['薄片形状的烹饪名称','phyllo']],contrasts='chlorophyll 不是叶子本身，phyllo 也不是用叶子做的面团；词根给出命名线索，实际所指仍要看完整单词。',practice='分别用 chlorophyll 和 phyllo 写一句植物观察与烹饪描述，解释同一个叶的画面为何进入不同场景。',words=rootwords(294),exclude=rootexclude(294))
FORNIC_ROOT=dict(id='C0445',meaning='拱顶、拱廊；场所名称产生的行为词',core='建筑空间的名字先被借来称某类场所，后来又转成在那里发生的行为名称。',image='拉丁 fornix 拱顶、拱廊；又有妓院义 → fornicari；fornicatio → 古法语 → fornication；fornicatus 及可能的英语逆构 → fornicate。',intro='fornication、fornicate 常见于宗教、旧道德或历史叙述，谈婚姻之外的性行为。解释它们时要说明时代与语气；这些词不是现代中性日常表达的唯一选择。',forms='fornix 的词干 fornic- 出现在相关词形中。fornication 在英语中早于 fornicate，不能为了整齐就把图画成英语动词先、名词后。',branches=[['行为类别与历史道德话语','fornication'],['相应动词','fornicate']],contrasts='与 adultery 的范围在不同传统中不完全一致。拱廊到场所的联系是传统解释，不表示建筑形状本身有道德含义。',practice='阅读历史材料时，先指出这个词反映谁的道德分类，再用现代中性的说法释义，避免把未婚关系一概误译为出轨。',words=rootwords(295),exclude=rootexclude(295))
AGAP_ROOT=dict(id='C0025',meaning='爱；无私关爱〔另辨同形张口词〕',core='关心对方的福祉，是爱之名词的核心；惊讶张嘴则来自另一条完全不同的线。',image='希腊 agapan 爱 → agape → 英语名词 agape；并列另源英语 a- + gape → agape 张口的。',intro='一个拼写容纳两个来源：/əˈɡeɪp/ 表示张着嘴，/ˈæɡəpi/ 等读法用于基督教之爱或爱宴。先用读音和上下文分开，再谈词根。',forms='张口义的最后 e 不发音，爱之名词通常三音节。张口义中的 a- 表示处于某状态，不是否定前缀；爱之名词来自希腊，不能这样拆。',branches=[['同形异源：张口与无私之爱','agape']],contrasts='不能把两词串成爱得惊讶所以张开嘴；那是临时联想，不是来源。agape 在神学中的含义也比普通恋爱场景更专门。',practice='分别用 mouth agape 和 the idea of agape 造句，并读出两个不同的读音。',words=rootwords(296),exclude=rootexclude(296))
CLE_ROOT=dict(id='C0236',meaning='呼叫；召集',core='把人叫到一处，便成为一个集会；人群的名称后来也用于教会共同体。',image='希腊 ek + kalein → ekkalein → ekklesia；古典集会到教会会众 → ecclesia；形容词支线 → ecclesiastic、ecclesiastical；近代组合 ecclesio- + -logy → ecclesiology。',intro='这组在历史与宗教阅读中有用。ecclesia 可以指古希腊公民大会，也可指教会群体；ecclesiastic 常是神职人员，ecclesiastical 是与教会事务有关的，ecclesiology 则研究教会的性质等问题。',forms='cle- 只是整理希腊呼叫词族的学习形式，常见整词包含 ecclesi-。不要把 ekklesia 仅仅当成建筑名：它的集会、会众背景更早。',branches=[['被召集起来的共同体','ecclesia'],['神职人员与教会事务','ecclesiastic, ecclesiastical'],['研究教会','ecclesiology']],contrasts='ecclesiastic 不等于任何信徒；ecclesiastical 一般修饰名词。church 虽常可作相应译词，却有另一条希腊来源，不能画成 ecclesia 的缩写。',practice='把一个群体、其中一位神职人员、该群体的组织事务分别写为 ecclesia、an ecclesiastic、ecclesiastical affairs。',words=rootwords(297,['ecclesiastical']),exclude=rootexclude(297))
